fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    debug_assert!(valores.len() >= 20 && valores.len() < 50);
    debug_assert!(i < valores.len() && j < valores.len() && k < valores.len());
    debug_assert!(i != j && i != k && j != k);

    let vi = valores[i];
    let vj = valores[j];
    let vk = valores[k];

    // Return the two indices among (i, j, k) with the highest values.
    // Order so that valores[first] >= valores[second].
    if vi >= vj {
        if vj >= vk {
            // vi >= vj >= vk
            (i, j)
        } else if vi >= vk {
            // vi >= vk > vj
            (i, k)
        } else {
            // vk > vi >= vj
            (k, i)
        }
    } else {
        // vj > vi
        if vi >= vk {
            // vj > vi >= vk
            (j, i)
        } else if vj >= vk {
            // vj >= vk > vi
            (j, k)
        } else {
            // vk > vj > vi
            (k, j)
        }
    }
}